import json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;checks=[]
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':390,'height':844},device_scale_factor=1);page.goto('http://127.0.0.1:5178');page.locator('.lab summary').click();page.locator('#locale').select_option('ru');page.locator('.lab summary').click();page.wait_for_function('document.querySelector("#scene").readyState>=3');page.locator('#record').click();page.wait_for_function('!document.querySelector("#take").disabled',timeout=10000);candidate=page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1")).candidates[0].id');page.locator('.lab summary').click();page.locator('#fail-mic').check();page.locator('.lab summary').click();page.locator('#record').click();expect(page.locator('#feedback')).to_be_visible();assert page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1")).candidates[0].id')==candidate;checks.append({'check':'Blocked recapture protects exact candidate','feedback':page.locator('#feedback').inner_text()});page.screenshot(path=str(out/'hf-review-ru-phone-input-error-full.png'),full_page=True);page.locator('#feedback button').click();expect(page.locator('#guard')).to_be_visible();checks.append({'check':'Settings recovery uses localized candidate exit guard','guard':page.locator('#guard').inner_text()});page.locator('#guard button').nth(2).click();expect(page.locator('#destination')).to_be_visible();assert page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1")).accepted[0].id')==candidate;checks.append({'check':'Save and leave accepts exact candidate before Settings boundary','boundary':page.locator('#destination').inner_text()});page.locator('#destination-close').click();expect(page.locator('#destination')).to_be_hidden();checks.append({'check':'Boundary close focus','id':page.evaluate('document.activeElement.id'),'name':page.evaluate('document.activeElement.innerText')});b.close()
(out/'hf-settings-recovery-review.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False),encoding='utf-8');print(json.dumps(checks,ensure_ascii=False,indent=2))
